solution.solution.c:
int minutes_part(int seconds)
{
    return seconds / 60;
}

int seconds_part(int seconds)
{
    return seconds % 60;
}

double average3(int a, int b, int c)
{
    return ((double)a + b + c) / 3.0;
}

int last_digit(int n)
{
    return n % 10;
}

int round_to(int n, int step)
{
    return (n + step / 2) / step * step;
}

unitTests:
TEST("minutes and seconds") { CHECK_EQ(minutes_part(125), 2); CHECK_EQ(seconds_part(125), 5); CHECK_EQ(minutes_part(59), 0); CHECK_EQ(seconds_part(3600), 0); }
TEST("an exact average") { CHECK_NEAR(average3(1, 2, 2), 5.0 / 3.0, 1e-9); CHECK_NEAR(average3(10, 20, 31), 61.0 / 3.0, 1e-9); CHECK_NEAR(average3(2000000000, 2000000000, 2000000000), 2000000000.0, 1e-3); }
TEST("last digit") { CHECK_EQ(last_digit(4072), 2); CHECK_EQ(last_digit(7), 7); CHECK_EQ(last_digit(0), 0); }
TEST("rounding to a step") { CHECK_EQ(round_to(17, 5), 15); CHECK_EQ(round_to(18, 5), 20); CHECK_EQ(round_to(25, 10), 30); CHECK_EQ(round_to(24, 10), 20); CHECK_EQ(round_to(0, 3), 0); }

